INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('omBU4qs110J', 4, '{"title":"第20200520条・玉机真脏论篇第十九","description":"<p>8、岐伯曰：夏脉者心也。南方火也。万物之所以盛长也。故其气来盛去衰。故曰钩。反此者病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200520,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '8、岐伯曰：夏脉者心也。南方火也。万物之所以盛长也。故其气来盛去衰。故曰钩。反此者病。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zWb2LIfa1dO', 4, '{"title":"第20200521条・玉机真脏论篇第十九","description":"<p>9、帝曰：何如而反？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200521,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '9、帝曰：何如而反？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WZP4FgTTNWA', 4, '{"title":"第20200522条・玉机真脏论篇第十九","description":"<p>10、岐伯曰：其气来盛去亦盛。此谓太过。病在外。其气来不盛去反盛。此谓不及。病在中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200522,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '10、岐伯曰：其气来盛去亦盛。此谓太过。病在外。其气来不盛去反盛。此谓不及。病在中。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I8jDMZuAUlB', 4, '{"title":"第20200523条・玉机真脏论篇第十九","description":"<p>11、帝曰： 夏脉太过与不及。其病皆何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200523,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '11、帝曰： 夏脉太过与不及。其病皆何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZM1Vm7D2AHM', 4, '{"title":"第20200524条・玉机真脏论篇第十九","description":"<p>12、岐伯曰：太过则令人身热而肤痛。为浸淫。其不及则令人烦心。上见咳唾。下为气泄。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200524,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '12、岐伯曰：太过则令人身热而肤痛。为浸淫。其不及则令人烦心。上见咳唾。下为气泄。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rvv415YYDsK', 4, '{"title":"第20200525条・玉机真脏论篇第十九","description":"<p>13、帝曰：善。秋脉如浮。何如而浮？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200525,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '13、帝曰：善。秋脉如浮。何如而浮？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GdYTvJBdN71', 4, '{"title":"第20200526条・玉机真脏论篇第十九","description":"<p>14、岐伯曰：秋脉者肺也。西方金也。万物之所以收成也。故其气来。轻虚以浮。来急去散。故曰浮。反此者病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200526,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '14、岐伯曰：秋脉者肺也。西方金也。万物之所以收成也。故其气来。轻虚以浮。来急去散。故曰浮。反此者病。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yql5y1inGvn', 4, '{"title":"第20200527条・玉机真脏论篇第十九","description":"<p>15、帝曰：何如而反？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200527,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '15、帝曰：何如而反？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lny6XUDfIj1', 4, '{"title":"第20200528条・玉机真脏论篇第十九","description":"<p>16、岐伯曰：其气来。毛而中央坚。两旁虚。此谓太过。病在外。其气来。毛而微。此谓不及。病在中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200528,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '16、岐伯曰：其气来。毛而中央坚。两旁虚。此谓太过。病在外。其气来。毛而微。此谓不及。病在中。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LcpgYQfwP4A', 4, '{"title":"第20200529条・玉机真脏论篇第十九","description":"<p>17、帝曰：秋脉太过与不及。其病皆何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200529,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '17、帝曰：秋脉太过与不及。其病皆何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5KVaF5KTStf', 4, '{"title":"第20200530条・玉机真脏论篇第十九","description":"<p>18、岐伯 曰：太过则令人逆气而背痛。愠愠然。其不及则令人喘。呼吸少气而咳。上气见血。下闻病音。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200530,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '18、岐伯 曰：太过则令人逆气而背痛。愠愠然。其不及则令人喘。呼吸少气而咳。上气见血。下闻病音。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cAnVuc8dtM3', 4, '{"title":"第20200531条・玉机真脏论篇第十九","description":"<p>19、帝曰：善。冬脉如营。何如而营？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200531,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '19、帝曰：善。冬脉如营。何如而营？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3zPoB1jqE25', 4, '{"title":"第20200532条・玉机真脏论篇第十九","description":"<p>20、岐伯曰：冬脉者肾也。北方水也。万物之所以合藏也。故其气来沉以搏。故曰营。反此者病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200532,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '20、岐伯曰：冬脉者肾也。北方水也。万物之所以合藏也。故其气来沉以搏。故曰营。反此者病。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3R505PaeLau', 4, '{"title":"第20200533条・玉机真脏论篇第十九","description":"<p>21、帝曰：何如而反？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200533,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '21、帝曰：何如而反？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g0mByxKsxcR', 4, '{"title":"第20200534条・玉机真脏论篇第十九","description":"<p>22、岐伯曰：其气来如弹石者。此谓太过。病在外。其去如数者。此谓不及。病在中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200534,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '22、岐伯曰：其气来如弹石者。此谓太过。病在外。其去如数者。此谓不及。病在中。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sutAa1oAvor', 4, '{"title":"第20200535条・玉机真脏论篇第十九","description":"<p>23、帝曰：冬脉太过与不及。其病皆何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200535,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '23、帝曰：冬脉太过与不及。其病皆何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZsDS8CVJ1ev', 4, '{"title":"第20200536条・玉机真脏论篇第十九","description":"<p>24、岐伯曰： 太过则令人解㑊。脊脉痛而少气不欲言。其不及则令人心悬如病饥。䏚中清。脊中痛。少腹满。小便变。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200536,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '24、岐伯曰： 太过则令人解㑊。脊脉痛而少气不欲言。其不及则令人心悬如病饥。䏚中清。脊中痛。少腹满。小便变。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0KJrAhpFHit', 4, '{"title":"第20200537条・玉机真脏论篇第十九","description":"<p>25、帝曰：善。帝曰：四时之序。逆从之变异也。然脾脉独何主？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200537,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '25、帝曰：善。帝曰：四时之序。逆从之变异也。然脾脉独何主？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UhBMOtdzFcP', 4, '{"title":"第20200538条・玉机真脏论篇第十九","description":"<p>26、岐伯曰：脾脉者土也。孤脏以灌四旁者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200538,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '26、岐伯曰：脾脉者土也。孤脏以灌四旁者也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yg91nxAJ45p', 4, '{"title":"第20200539条・玉机真脏论篇第十九","description":"<p>27、帝曰：然则脾善恶。可得见之乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200539,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '27、帝曰：然则脾善恶。可得见之乎？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A71rs7NlQwt', 4, '{"title":"第20200540条・玉机真脏论篇第十九","description":"<p>28、岐伯曰：善者不可得见。恶者可见。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200540,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '28、岐伯曰：善者不可得见。恶者可见。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ELgfz1vtxoh', 4, '{"title":"第20200541条・玉机真脏论篇第十九","description":"<p>29、帝曰：恶者何如可见？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200541,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '29、帝曰：恶者何如可见？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VdSFL36TWj0', 4, '{"title":"第20200542条・玉机真脏论篇第十九","description":"<p>30、岐伯曰： 其来如水之流者。此谓太过。病在外。如鸟之喙者。此谓不及。病在中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200542,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '30、岐伯曰： 其来如水之流者。此谓太过。病在外。如鸟之喙者。此谓不及。病在中。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tdkurI4pv5w', 4, '{"title":"第20200543条・玉机真脏论篇第十九","description":"<p>31、帝曰：夫子言脾为孤脏。中央土以灌四旁。其太过与不及。其病皆何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200543,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '31、帝曰：夫子言脾为孤脏。中央土以灌四旁。其太过与不及。其病皆何如？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('He5zaaJPjOA', 4, '{"title":"第20200544条・玉机真脏论篇第十九","description":"<p>32、岐伯曰：太过则令人四肢不举。其不及。则令人九窍不通。名曰重强。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200544,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '32、岐伯曰：太过则令人四肢不举。其不及。则令人九窍不通。名曰重强。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3z2SeYI4bDK', 4, '{"title":"第20200545条・玉机真脏论篇第十九","description":"<p>33、帝瞿然而起。再拜而稽首曰：善。吾得脉之大要。天下至数。五色脉变。揆度奇恒。道在于一。神转不回。回则不转。乃失其机。至数之要。迫近以微。着之玉版。藏之脏腑。每旦读之。名曰《玉机》。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200545,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '33、帝瞿然而起。再拜而稽首曰：善。吾得脉之大要。天下至数。五色脉变。揆度奇恒。道在于一。神转不回。回则不转。乃失其机。至数之要。迫近以微。着之玉版。藏之脏腑。每旦读之。名曰《玉机》。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M7as41G7Gs7', 4, '{"title":"第20200546条・玉机真脏论篇第十九","description":"<p>34、五脏受气于其所生。传之于其所胜。气舍于其所生。死于其所不胜。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200546,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '34、五脏受气于其所生。传之于其所胜。气舍于其所生。死于其所不胜。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IqCsepI94Sy', 4, '{"title":"第20200547条・玉机真脏论篇第十九","description":"<p>35、病之且死。必先传行至其所不胜。病乃死。此言气之逆行也。故死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200547,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '35、病之且死。必先传行至其所不胜。病乃死。此言气之逆行也。故死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O3kDVch86Yh', 4, '{"title":"第20200548条・玉机真脏论篇第十九","description":"<p>36、肝受气于心。传之于脾。气舍于肾。至肺而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200548,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '36、肝受气于心。传之于脾。气舍于肾。至肺而死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
