INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FbC2wCghdpp', 4, '{"title":"第20200553条・玉机真脏论篇第十九","description":"<p>41、此皆逆死也。一日一夜五分之。此所以占死 生之早暮也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200553,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '41、此皆逆死也。一日一夜五分之。此所以占死 生之早暮也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YKdQolcOWqO', 4, '{"title":"第20200554条・玉机真脏论篇第十九","description":"<p>42、黄帝曰：五脏相通。移皆有次。五脏有病。则各传其所胜。不治。法三月若六月。若三日若六日。传五脏而当死。是顺传所胜之次。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200554,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '42、黄帝曰：五脏相通。移皆有次。五脏有病。则各传其所胜。不治。法三月若六月。若三日若六日。传五脏而当死。是顺传所胜之次。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EBaOI3t5hK7', 4, '{"title":"第20200555条・玉机真脏论篇第十九","description":"<p>43、故曰：别于阳者。知病从来。别于阴者。知死生之期。言知至其所困而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200555,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '43、故曰：别于阳者。知病从来。别于阴者。知死生之期。言知至其所困而死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WoycF7ImanK', 4, '{"title":"第20200556条・玉机真脏论篇第十九","description":"<p>44、是故风者百病之长也。今风寒客于人。使人毫毛毕直。皮肤闭而为热。当是之时。可汗而发也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200556,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '44、是故风者百病之长也。今风寒客于人。使人毫毛毕直。皮肤闭而为热。当是之时。可汗而发也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9giAOVKdtkG', 4, '{"title":"第20200557条・玉机真脏论篇第十九","description":"<p>45、或痹不仁肿痛。当是之时。可汤熨及火灸刺而去之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200557,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '45、或痹不仁肿痛。当是之时。可汤熨及火灸刺而去之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mjAqUGCLlvS', 4, '{"title":"第20200558条・玉机真脏论篇第十九","description":"<p>46、弗治。病入舍于肺。名曰肺痹。 发咳上气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200558,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '46、弗治。病入舍于肺。名曰肺痹。 发咳上气。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uF1w41hAH4L', 4, '{"title":"第20200559条・玉机真脏论篇第十九","description":"<p>47、弗治。肺即传而行之肝。病名曰肝痹。一名曰厥。胁痛出食。当是之时。可按若刺耳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200559,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '47、弗治。肺即传而行之肝。病名曰肝痹。一名曰厥。胁痛出食。当是之时。可按若刺耳。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('40zX53ZOqgC', 4, '{"title":"第20200560条・玉机真脏论篇第十九","description":"<p>48、弗治。肝传之脾。病名曰脾风。发瘅。腹中热。烦心出黄。当此之时。可按可药可浴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200560,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '48、弗治。肝传之脾。病名曰脾风。发瘅。腹中热。烦心出黄。当此之时。可按可药可浴。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2cSr1qXXA9t', 4, '{"title":"第20200561条・玉机真脏论篇第十九","description":"<p>49、弗治。脾传之肾。病名曰疝瘕。少腹冤热而痛。出白。一名曰蛊。当此之时，。可按可药。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200561,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '49、弗治。脾传之肾。病名曰疝瘕。少腹冤热而痛。出白。一名曰蛊。当此之时，。可按可药。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jXv8wwLfZZ7', 4, '{"title":"第20200562条・玉机真脏论篇第十九","description":"<p>50、弗治。肾传之心。病筋脉相引而急。病名曰螈。当此之时。可灸可药。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200562,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '50、弗治。肾传之心。病筋脉相引而急。病名曰螈。当此之时。可灸可药。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fZvgD2ReYTO', 4, '{"title":"第20200563条・玉机真脏论篇第十九","description":"<p>51、弗治。满十日。法当死。肾因传之心。心即复反传而行之肺。发寒热。法当三岁死。此病之次也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200563,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '51、弗治。满十日。法当死。肾因传之心。心即复反传而行之肺。发寒热。法当三岁死。此病之次也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u9zLJ1qSLCQ', 4, '{"title":"第20200564条・玉机真脏论篇第十九","description":"<p>52、然其卒发者。不必治于传。或其传化有不以次。不以次入者。忧恐悲喜怒。令不得以其次。故令人有大病矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200564,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '52、然其卒发者。不必治于传。或其传化有不以次。不以次入者。忧恐悲喜怒。令不得以其次。故令人有大病矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('upDSojnkEK0', 4, '{"title":"第20200565条・玉机真脏论篇第十九","description":"<p>53、因而喜大虚则肾气乘矣。怒则肝气乘矣。悲则肺气乘矣。恐则脾气乘矣。忧则心气乘矣。此其道也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200565,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '53、因而喜大虚则肾气乘矣。怒则肝气乘矣。悲则肺气乘矣。恐则脾气乘矣。忧则心气乘矣。此其道也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Mo1XjnhS2Mv', 4, '{"title":"第20200566条・玉机真脏论篇第十九","description":"<p>54、故病有五。五五二十五变。及其传化。传。乘之名也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200566,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '54、故病有五。五五二十五变。及其传化。传。乘之名也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KojtZ0AuWyv', 4, '{"title":"第20200567条・玉机真脏论篇第十九","description":"<p>55、大骨枯槁。大肉陷下。胸中气满。喘息不便。其气动形。期六月死。真脏脉见。乃予之期日。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200567,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '55、大骨枯槁。大肉陷下。胸中气满。喘息不便。其气动形。期六月死。真脏脉见。乃予之期日。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l6Ti9rDGyLv', 4, '{"title":"第20200568条・玉机真脏论篇第十九","description":"<p>56、大骨枯槁。大肉陷下。胸中气满。喘息不便。内痛引肩项。期一月死。真脏见。乃予之期日。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200568,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '56、大骨枯槁。大肉陷下。胸中气满。喘息不便。内痛引肩项。期一月死。真脏见。乃予之期日。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q6ZSgWGP57u', 4, '{"title":"第20200569条・玉机真脏论篇第十九","description":"<p>57、大骨枯槁。大肉陷下。胸中气满。喘息不便。内痛引肩项。身热脱肉破。真脏见。十月之内死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200569,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '57、大骨枯槁。大肉陷下。胸中气满。喘息不便。内痛引肩项。身热脱肉破。真脏见。十月之内死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r6HCN3oZz5n', 4, '{"title":"第20200570条・玉机真脏论篇第十九","description":"<p>58、大骨枯槁。大肉陷下。肩髓内消。动作益衰。真脏来见。期一岁死。见其真脏。乃予之期日。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200570,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '58、大骨枯槁。大肉陷下。肩髓内消。动作益衰。真脏来见。期一岁死。见其真脏。乃予之期日。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VC7qTo2ecJF', 4, '{"title":"第20200571条・玉机真脏论篇第十九","description":"<p>59、大骨枯槁。大肉陷下。胸中气满。腹内痛。心中不便。肩项身热。破?脱肉。目匡陷。真脏见。目不见人。立死。其见人者。至其所不胜之时则死。急虚身中卒至。五脏绝闭。脉道不通。气不往来。譬于堕溺。不可为期。其脉绝不来。若人一息五六至。其形肉不脱。真脏虽不见。犹死也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200571,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '59、大骨枯槁。大肉陷下。胸中气满。腹内痛。心中不便。肩项身热。破?脱肉。目匡陷。真脏见。目不见人。立死。其见人者。至其所不胜之时则死。急虚身中卒至。五脏绝闭。脉道不通。气不往来。譬于堕溺。不可为期。其脉绝不来。若人一息五六至。其形肉不脱。真脏虽不见。犹死也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FHDkHKEgqLV', 4, '{"title":"第20200572条・玉机真脏论篇第十九","description":"<p>60、真肝脉至。中外急。如循刀刃责责然。如按琴瑟弦。色青白不泽。毛折。乃死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200572,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '60、真肝脉至。中外急。如循刀刃责责然。如按琴瑟弦。色青白不泽。毛折。乃死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VnwwjhhniYT', 4, '{"title":"第20200573条・玉机真脏论篇第十九","description":"<p>61、真心脉至。坚而搏。如循薏苡子累累然。色赤黑不泽。毛折。乃死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200573,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '61、真心脉至。坚而搏。如循薏苡子累累然。色赤黑不泽。毛折。乃死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4BFX5exAa4a', 4, '{"title":"第20200574条・玉机真脏论篇第十九","description":"<p>62、真肺脉至。大而虚。如以毛羽中人肤。色白赤不泽。毛折。乃死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200574,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '62、真肺脉至。大而虚。如以毛羽中人肤。色白赤不泽。毛折。乃死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9r7pVaXQ3DY', 4, '{"title":"第20200575条・玉机真脏论篇第十九","description":"<p>63、真肾脉至。搏而绝。如指弹石辟辟然。色黑黄不泽。毛折。乃死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200575,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '63、真肾脉至。搏而绝。如指弹石辟辟然。色黑黄不泽。毛折。乃死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dx1SiMbYbcH', 4, '{"title":"第20200576条・玉机真脏论篇第十九","description":"<p>64、真脾脉至。弱而乍数乍疏。色黄青不泽。毛折。乃死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200576,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '64、真脾脉至。弱而乍数乍疏。色黄青不泽。毛折。乃死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('22jTca8usAE', 4, '{"title":"第20200577条・玉机真脏论篇第十九","description":"<p>65、诸真藏脉见者。皆死不治也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200577,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '65、诸真藏脉见者。皆死不治也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3E5IAO6qASS', 4, '{"title":"第20200578条・玉机真脏论篇第十九","description":"<p>66、黄帝曰： 见真藏曰死。何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200578,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '66、黄帝曰： 见真藏曰死。何也？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OwYdJ94Pe8i', 4, '{"title":"第20200579条・玉机真脏论篇第十九","description":"<p>67、岐伯曰： 五藏者皆禀气于胃。胃者五藏之本也。藏气者。不能自致于手太阴。必因于胃气。乃至于手太阴也。故五藏各以其时。自为而至于手太阴也。故邪气胜者。精气衰也。故病甚者。胃气不能与之俱至于手太阴。故真藏之气独见。独见者病胜藏也。故曰死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200579,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '67、岐伯曰： 五藏者皆禀气于胃。胃者五藏之本也。藏气者。不能自致于手太阴。必因于胃气。乃至于手太阴也。故五藏各以其时。自为而至于手太阴也。故邪气胜者。精气衰也。故病甚者。胃气不能与之俱至于手太阴。故真藏之气独见。独见者病胜藏也。故曰死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZVwZHA75FMD', 4, '{"title":"第20200580条・玉机真脏论篇第十九","description":"<p>68、帝曰：善。 黄帝曰：凡治病，察其形气色泽。脉之盛衰。病之新故。乃治之无后其时。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200580,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '68、帝曰：善。 黄帝曰：凡治病，察其形气色泽。脉之盛衰。病之新故。乃治之无后其时。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sO2OMt4hzAW', 4, '{"title":"第20200581条・玉机真脏论篇第十九","description":"<p>69、形气相得。谓之可治。色泽以浮。谓之易已。脉从四时。谓之可治。脉弱以滑。是有胃气。命曰易治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200581,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '69、形气相得。谓之可治。色泽以浮。谓之易已。脉从四时。谓之可治。脉弱以滑。是有胃气。命曰易治。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i5dEaa0RpOL', 4, '{"title":"第20200582条・玉机真脏论篇第十九","description":"<p>70、取之以时。形气相失。谓之难治。色夭不泽。谓之难已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200582,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '70、取之以时。形气相失。谓之难治。色夭不泽。谓之难已。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gk8oCpgChiG', 4, '{"title":"第20200583条・玉机真脏论篇第十九","description":"<p>71、脉实以坚。谓之益甚。脉逆四时。为不可治。必察四难。而明告之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200583,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '71、脉实以坚。谓之益甚。脉逆四时。为不可治。必察四难。而明告之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J2w8JCgViBf', 4, '{"title":"第20200584条・玉机真脏论篇第十九","description":"<p>72、所谓逆四时者。春得肺脉。夏得肾脉。秋得心脉。冬得脾脉。其至皆悬绝沉涩者。命曰逆四时。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200584,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '72、所谓逆四时者。春得肺脉。夏得肾脉。秋得心脉。冬得脾脉。其至皆悬绝沉涩者。命曰逆四时。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xs8Abkuj5jR', 4, '{"title":"第20200585条・玉机真脏论篇第十九","description":"<p>73、未有藏形。于春夏而脉沉涩。秋冬而脉浮大。名曰逆四时也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200585,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '73、未有藏形。于春夏而脉沉涩。秋冬而脉浮大。名曰逆四时也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('obBnheNP79v', 4, '{"title":"第20200586条・玉机真脏论篇第十九","description":"<p>74、病热脉静。泄而脉大。脱血而脉实。病在中脉实坚。病在外脉不实坚者。皆难治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200586,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '74、病热脉静。泄而脉大。脱血而脉实。病在中脉实坚。病在外脉不实坚者。皆难治。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7kb38se25ts', 4, '{"title":"第20200587条・玉机真脏论篇第十九","description":"<p>75、黄帝曰：余闻虚实以决死生。愿闻其情。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200587,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '75、黄帝曰：余闻虚实以决死生。愿闻其情。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BGCXxj686CQ', 4, '{"title":"第20200588条・玉机真脏论篇第十九","description":"<p>76、岐伯曰：五实死。五虚死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200588,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '76、岐伯曰：五实死。五虚死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lR7O7ziWbhR', 4, '{"title":"第20200589条・玉机真脏论篇第十九","description":"<p>77、帝曰：愿闻五实五虚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200589,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '77、帝曰：愿闻五实五虚。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z6C69BTD49z', 4, '{"title":"第20200590条・玉机真脏论篇第十九","description":"<p>78、岐伯曰：脉盛。皮热。腹胀。前后不通。闷瞀。此谓五实。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200590,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '78、岐伯曰：脉盛。皮热。腹胀。前后不通。闷瞀。此谓五实。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nnsjGCQpF8I', 4, '{"title":"第20200591条・玉机真脏论篇第十九","description":"<p>79、脉细。皮寒。气少。泄利前后。饮食不入。此谓五虚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200591,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '79、脉细。皮寒。气少。泄利前后。饮食不入。此谓五虚。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cxw9lfrhDuI', 4, '{"title":"第20200592条・玉机真脏论篇第十九","description":"<p>80、帝曰：其时有生者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200592,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '80、帝曰：其时有生者何也？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3jn2q09YXyL', 4, '{"title":"第20200593条・玉机真脏论篇第十九","description":"<p>81、岐伯曰：浆粥入胃。泄注止。则虚者活。身汗得后利。则实者活。此其候也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200593,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '81、岐伯曰：浆粥入胃。泄注止。则虚者活。身汗得后利。则实者活。此其候也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hc7dbjqxm2B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zTOIwyhn3sr', 4, '{"title":"第20200594条・三部九候论篇第二十","description":"<p>1、黄帝问曰：余闻九针于夫子。众多博大。不可胜数。余愿闻要道。以属子孙。传之后世。着之骨髓。藏之肝肺。歃血而受。不敢妄泄。令合天道。必有终始，上应天光星辰历纪。下副四时五行。贵贱更立。冬阴夏阳。以人应之奈何？愿闻其方。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200594,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、黄帝问曰：余闻九针于夫子。众多博大。不可胜数。余愿闻要道。以属子孙。传之后世。着之骨髓。藏之肝肺。歃血而受。不敢妄泄。令合天道。必有终始，上应天光星辰历纪。下副四时五行。贵贱更立。冬阴夏阳。以人应之奈何？愿闻其方。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lVYhIHLLeKe', 4, '{"title":"第20200595条・三部九候论篇第二十","description":"<p>2、岐伯对曰：妙乎哉问也！此天地之至数。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200595,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、岐伯对曰：妙乎哉问也！此天地之至数。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RpJCYvF19F4', 4, '{"title":"第20200596条・三部九候论篇第二十","description":"<p>3、帝曰：愿闻天地 之至数。合于人形血气。通决死生。为之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200596,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、帝曰：愿闻天地 之至数。合于人形血气。通决死生。为之奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7mvvrWSoA2f', 4, '{"title":"第20200597条・三部九候论篇第二十","description":"<p>4、岐伯曰：天地之至数。始于一。终于九焉。一者天。二者 地。三者人。因而三之。三三者九。以应九野。故人有三部。部有三候。以决死生。以处百病。以调虚实。而除邪疾。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200597,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、岐伯曰：天地之至数。始于一。终于九焉。一者天。二者 地。三者人。因而三之。三三者九。以应九野。故人有三部。部有三候。以决死生。以处百病。以调虚实。而除邪疾。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FTV0z8thk6S', 4, '{"title":"第20200598条・三部九候论篇第二十","description":"<p>5、帝曰：何谓三部？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200598,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、帝曰：何谓三部？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pCvR44NrxcF', 4, '{"title":"第20200599条・三部九候论篇第二十","description":"<p>6、岐伯曰：有下部。有中部。有上部。部各有三候。三候者。有天有地有人也。必指而导之。乃以为真。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200599,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、岐伯曰：有下部。有中部。有上部。部各有三候。三候者。有天有地有人也。必指而导之。乃以为真。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
