INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e4ms57FrUDJ', 4, '{"title":"第20200607条・三部九候论篇第二十","description":"<p>14、岐伯曰：亦有天。亦有地。亦有人。天以候头角之气。地以候口齿之气。人以候耳目之气。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200607,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '14、岐伯曰：亦有天。亦有地。亦有人。天以候头角之气。地以候口齿之气。人以候耳目之气。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6B9Y7nLAYf7', 4, '{"title":"第20200608条・三部九候论篇第二十","description":"<p>15、三部者。各有天。各有地， 。各有人。三而成天。三而成地。三而成人。三而三之。合则为九。九分为九野。九野为九藏。故神藏五。形藏四。合为九藏。五藏已败。其色必夭。夭必死矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200608,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '15、三部者。各有天。各有地， 。各有人。三而成天。三而成地。三而成人。三而三之。合则为九。九分为九野。九野为九藏。故神藏五。形藏四。合为九藏。五藏已败。其色必夭。夭必死矣。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0u0CwVmDp13', 4, '{"title":"第20200609条・三部九候论篇第二十","description":"<p>16、帝曰：以候奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200609,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '16、帝曰：以候奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jhg5MaAiEOd', 4, '{"title":"第20200610条・三部九候论篇第二十","description":"<p>17、岐伯曰：必先度其形之肥瘦。以调其气之虚实。实则泻之。虚则补之。必先去其血脉而后调之。无问其病。以平为期。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200610,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '17、岐伯曰：必先度其形之肥瘦。以调其气之虚实。实则泻之。虚则补之。必先去其血脉而后调之。无问其病。以平为期。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P1HAfFD2nMe', 4, '{"title":"第20200611条・三部九候论篇第二十","description":"<p>18、帝曰：决死生奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200611,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '18、帝曰：决死生奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r40QuO0u07K', 4, '{"title":"第20200612条・三部九候论篇第二十","description":"<p>19、岐伯曰：形盛脉细。少气不足以息者危。 形瘦脉大。胸中多气者死。形气相得者生。参伍不调者病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200612,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '19、岐伯曰：形盛脉细。少气不足以息者危。 形瘦脉大。胸中多气者死。形气相得者生。参伍不调者病。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e3pL5YqffT8', 4, '{"title":"第20200613条・三部九候论篇第二十","description":"<p>20、三部九候皆相失者死。上下左右之脉相应如参舂者病甚。上下左右相失不可数者死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200613,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '20、三部九候皆相失者死。上下左右之脉相应如参舂者病甚。上下左右相失不可数者死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RHgQC5rbcsr', 4, '{"title":"第20200614条・三部九候论篇第二十","description":"<p>21、中部之候虽独调。与众脏相失者死。中部之候相减者死。目内陷者死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200614,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '21、中部之候虽独调。与众脏相失者死。中部之候相减者死。目内陷者死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sDAbswulpr3', 4, '{"title":"第20200615条・三部九候论篇第二十","description":"<p>22、帝曰：何以知病之所在？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200615,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '22、帝曰：何以知病之所在？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x4lZ3BA5DHj', 4, '{"title":"第20200616条・三部九候论篇第二十","description":"<p>23、岐伯曰：察九候独小者病。独大者病。独疾者病。独迟者病。独热者病。独寒者病。独陷下者病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200616,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '23、岐伯曰：察九候独小者病。独大者病。独疾者病。独迟者病。独热者病。独寒者病。独陷下者病。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mrLNBOeu4VR', 4, '{"title":"第20200617条・三部九候论篇第二十","description":"<p>24、以左手足上上去踝五寸按之。庶右手足当踝而弹之。其应过五寸以上。蠕蠕然者不病。其应疾。中手浑浑然者病。中手徐徐然者病。其应上不能至五寸。弹之不应者死。是以脱肉身不去者死。中部乍疏乍数者死。其脉代而钩者。病在络脉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200617,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '24、以左手足上上去踝五寸按之。庶右手足当踝而弹之。其应过五寸以上。蠕蠕然者不病。其应疾。中手浑浑然者病。中手徐徐然者病。其应上不能至五寸。弹之不应者死。是以脱肉身不去者死。中部乍疏乍数者死。其脉代而钩者。病在络脉。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HUbwlzr2tAf', 4, '{"title":"第20200618条・三部九候论篇第二十","description":"<p>25、九候之相应也。上下若一。不得相失。一候后则病。二候后则病甚。三候后则病危。所谓后者。应不俱也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200618,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '25、九候之相应也。上下若一。不得相失。一候后则病。二候后则病甚。三候后则病危。所谓后者。应不俱也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IxdlEkHM7wW', 4, '{"title":"第20200619条・三部九候论篇第二十","description":"<p>26、察其腑藏。以知死生之期。必先知经脉。然后知病脉。真藏脉见者胜死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200619,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '26、察其腑藏。以知死生之期。必先知经脉。然后知病脉。真藏脉见者胜死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vwn1sV3GumW', 4, '{"title":"第20200620条・三部九候论篇第二十","description":"<p>27、足太阳气绝者。其足不可屈伸。死必戴眼。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200620,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '27、足太阳气绝者。其足不可屈伸。死必戴眼。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Qx2bbBPW2h3', 4, '{"title":"第20200621条・三部九候论篇第二十","description":"<p>28、帝曰：冬阴夏阳奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200621,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '28、帝曰：冬阴夏阳奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0rfkX7j8nPc', 4, '{"title":"第20200622条・三部九候论篇第二十","description":"<p>29、岐伯曰：九候之脉。皆沉细悬绝者 。为阴。主冬。故以夜半死。盛躁喘数者为阳。主夏。故以日中死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200622,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '29、岐伯曰：九候之脉。皆沉细悬绝者 。为阴。主冬。故以夜半死。盛躁喘数者为阳。主夏。故以日中死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pY1MqSNCk9Q', 4, '{"title":"第20200623条・三部九候论篇第二十","description":"<p>30、是故寒热病者。以平旦死。热中及热病者。以日中死。病风者。以日夕死。病水者。以夜半死。其脉乍疏乍数乍迟乍疾者。日乘四季死。形肉已脱。九候虽调。犹死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200623,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '30、是故寒热病者。以平旦死。热中及热病者。以日中死。病风者。以日夕死。病水者。以夜半死。其脉乍疏乍数乍迟乍疾者。日乘四季死。形肉已脱。九候虽调。犹死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Blwk0vpMdGf', 4, '{"title":"第20200624条・三部九候论篇第二十","description":"<p>31、七诊虽见。九候皆从者不死。所言不死者。风气之病及经月之病。似七诊之病而非也。故言不死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200624,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '31、七诊虽见。九候皆从者不死。所言不死者。风气之病及经月之病。似七诊之病而非也。故言不死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Eg5yfkDfrHc', 4, '{"title":"第20200625条・三部九候论篇第二十","description":"<p>32、若有七诊之病。其脉候亦败者死矣。必发哕噫。必审问其所始病。与今之所方病。而后各切循其脉。视其经络浮沉。以上下逆从循之。其脉疾者不病。其脉迟者病。脉不往来者死。皮肤着者死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200625,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '32、若有七诊之病。其脉候亦败者死矣。必发哕噫。必审问其所始病。与今之所方病。而后各切循其脉。视其经络浮沉。以上下逆从循之。其脉疾者不病。其脉迟者病。脉不往来者死。皮肤着者死。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MLovc4njUvf', 4, '{"title":"第20200626条・三部九候论篇第二十","description":"<p>33、帝曰：其可治者奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200626,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '33、帝曰：其可治者奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U2UaccTYb2N', 4, '{"title":"第20200627条・三部九候论篇第二十","description":"<p>34、岐伯曰：经病者治其经。孙络病者治其孙络血。血病身有痛者治其经络。其病者在奇邪。奇邪之脉则缪刺之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200627,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '34、岐伯曰：经病者治其经。孙络病者治其孙络血。血病身有痛者治其经络。其病者在奇邪。奇邪之脉则缪刺之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gYsg3hW4E36', 4, '{"title":"第20200628条・三部九候论篇第二十","description":"<p>35、留瘦不移。节而刺之。上实下虚。切而从之。索其结络脉。刺出其血。以见通之。瞳子高者太阳不足。戴眼者太阳已绝。此决死生之要。不可不察也。手指及手外踝上五指留针。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200628,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '35、留瘦不移。节而刺之。上实下虚。切而从之。索其结络脉。刺出其血。以见通之。瞳子高者太阳不足。戴眼者太阳已绝。此决死生之要。不可不察也。手指及手外踝上五指留针。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'x2s4abmcIW4');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZaH4jG4Rz5O', 4, '{"title":"第20200629条・经脉别论篇第二十一","description":"<p>1、黄帝问曰：人之居处动静勇怯。脉亦为之变乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200629,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、黄帝问曰：人之居处动静勇怯。脉亦为之变乎？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8DTOTF6De8l', 4, '{"title":"第20200630条・经脉别论篇第二十一","description":"<p>2、岐伯对曰：凡人之惊恐恚劳动静。皆为变也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200630,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、岐伯对曰：凡人之惊恐恚劳动静。皆为变也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
