INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Y4VXaYjwnm', 4, '{"title":"第20200632条・经脉别论篇第二十一","description":"<p>4、有所堕恐，喘出于肝。淫气害脾。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200632,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、有所堕恐，喘出于肝。淫气害脾。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
