INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IkxcZF9CtuU', 4, '{"title":"第20200642条・经脉别论篇第二十一","description":"<p>14、故春秋冬夏。四时阴阳。生病起于过用。此为常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200642,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '14、故春秋冬夏。四时阴阳。生病起于过用。此为常也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1C45L21sdDX', 4, '{"title":"第20200643条・经脉别论篇第二十一","description":"<p>15、食气入胃。散精于肝。淫气于筋。食气入胃。浊气归心。淫精于脉。脉气流经。经气归于肺。肺朝百脉。输精于皮毛。毛脉合精。行气于腑。腑精神明。留于四藏。气归于权衡。权衡以平。气口成寸。以决死生。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200643,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '15、食气入胃。散精于肝。淫气于筋。食气入胃。浊气归心。淫精于脉。脉气流经。经气归于肺。肺朝百脉。输精于皮毛。毛脉合精。行气于腑。腑精神明。留于四藏。气归于权衡。权衡以平。气口成寸。以决死生。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TLVg7I3mwJw', 4, '{"title":"第20200644条・经脉别论篇第二十一","description":"<p>16、饮入于胃。游溢精气。上输于脾。脾气散精。上归于肺。通调水道。下输膀胱。水精四布。五经并行。合于四时五藏阴阳。揆度以为常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200644,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '16、饮入于胃。游溢精气。上输于脾。脾气散精。上归于肺。通调水道。下输膀胱。水精四布。五经并行。合于四时五藏阴阳。揆度以为常也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fRdL47EkXHV', 4, '{"title":"第20200645条・经脉别论篇第二十一","description":"<p>17、太阳藏独至。厥喘虚气逆。是阴不足阳有余也。表里当俱泻。取之下俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200645,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '17、太阳藏独至。厥喘虚气逆。是阴不足阳有余也。表里当俱泻。取之下俞。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bjgpfkp3tMn', 4, '{"title":"第20200646条・经脉别论篇第二十一","description":"<p>18、阳明藏独至。是阳气重并也。当泻阳补阴。取之下俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200646,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '18、阳明藏独至。是阳气重并也。当泻阳补阴。取之下俞。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TrrMrWqs57i', 4, '{"title":"第20200647条・经脉别论篇第二十一","description":"<p>19、少阳藏独至。是厥气也。跷前卒大。取之下俞。少阳独至者。一阳之过也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200647,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '19、少阳藏独至。是厥气也。跷前卒大。取之下俞。少阳独至者。一阳之过也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BIZF2D070dH', 4, '{"title":"第20200648条・经脉别论篇第二十一","description":"<p>20、太阴藏搏者。用心省真。五脉气少。胃气不平。三阴也。宜治其下俞。补阳泻阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200648,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '20、太阴藏搏者。用心省真。五脉气少。胃气不平。三阴也。宜治其下俞。补阳泻阴。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iW9q0QfJL8G', 4, '{"title":"第20200649条・经脉别论篇第二十一","description":"<p>21、一阳独啸。少阳厥也。阳并于上。四脉争张。气归于肾。宜治其经络。泻阳补阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200649,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '21、一阳独啸。少阳厥也。阳并于上。四脉争张。气归于肾。宜治其经络。泻阳补阴。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4VHFtpDQpWO', 4, '{"title":"第20200650条・经脉别论篇第二十一","description":"<p>22、一阴至。厥阴之治也。真虚?心。厥气留薄。发为白汗。调食和药。治在下俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200650,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '22、一阴至。厥阴之治也。真虚?心。厥气留薄。发为白汗。调食和药。治在下俞。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
