INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ep1oL0632Ka', 4, '{"title":"第20200656条・经脉别论篇第二十一","description":"<p>28、岐伯曰：象大浮也太阴藏搏。言伏鼓也。二阴搏至。肾沉不浮也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200656,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '28、岐伯曰：象大浮也太阴藏搏。言伏鼓也。二阴搏至。肾沉不浮也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'hHaB9DM2tS2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HiOZ66TlF3z', 4, '{"title":"第20200657条・脏气法时论篇第二十二","description":"<p>1、黄帝问曰：合人形以法四时五行而治。何如而从？何如而逆？得失之意。愿闻其事。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200657,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、黄帝问曰：合人形以法四时五行而治。何如而从？何如而逆？得失之意。愿闻其事。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YOpmXxuo0IN', 4, '{"title":"第20200658条・脏气法时论篇第二十二","description":"<p>2、岐伯对曰：五行者。金木水火土也。更贵更贱。以知死生。以决成败。而定五脏之。间甚之时。死生之期也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200658,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、岐伯对曰：五行者。金木水火土也。更贵更贱。以知死生。以决成败。而定五脏之。间甚之时。死生之期也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q3uqHc1uT72', 4, '{"title":"第20200659条・脏气法时论篇第二十二","description":"<p>3、帝曰：愿卒闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200659,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、帝曰：愿卒闻之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u7LxLhzzKB7', 4, '{"title":"第20200660条・脏气法时论篇第二十二","description":"<p>4、岐伯曰：肝主春。足厥阴少阳主治。其日甲乙。肝苦急。急食甘以缓之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200660,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、岐伯曰：肝主春。足厥阴少阳主治。其日甲乙。肝苦急。急食甘以缓之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BqI1MGiFelD', 4, '{"title":"第20200661条・脏气法时论篇第二十二","description":"<p>5、心主夏。手少阴太阳主治。其日丙丁。心苦缓。急食酸以收之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200661,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、心主夏。手少阴太阳主治。其日丙丁。心苦缓。急食酸以收之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0x52BG7KK0E', 4, '{"title":"第20200662条・脏气法时论篇第二十二","description":"<p>6、脾主长夏。足太阴阳明主治。其日戊己。脾苦湿。急食苦以燥之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200662,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、脾主长夏。足太阴阳明主治。其日戊己。脾苦湿。急食苦以燥之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2uukEDfmr82', 4, '{"title":"第20200663条・脏气法时论篇第二十二","description":"<p>7、肺主秋。手太阴阳明主治。其日庚辛。肺苦气上逆。急食苦以泄之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200663,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '7、肺主秋。手太阴阳明主治。其日庚辛。肺苦气上逆。急食苦以泄之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3mYIU4e3auV', 4, '{"title":"第20200664条・脏气法时论篇第二十二","description":"<p>8、肾主冬。足少阴太阳主治。其日壬癸。肾苦燥。急食辛以润之。开腠理。致津液。通气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200664,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '8、肾主冬。足少阴太阳主治。其日壬癸。肾苦燥。急食辛以润之。开腠理。致津液。通气也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rZldSbsq3uw', 4, '{"title":"第20200665条・脏气法时论篇第二十二","description":"<p>9、病在肝。愈于夏。夏不愈。甚于秋。秋不死。持于冬。起于春。禁当风。肝病者。愈在丙丁。丙丁不愈。加于庚辛。庚辛不死。持于壬癸。起于甲乙。肝病者。平旦慧。下晡甚。夜半静。肝欲散。急食辛以散之。用辛补之。酸泻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200665,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '9、病在肝。愈于夏。夏不愈。甚于秋。秋不死。持于冬。起于春。禁当风。肝病者。愈在丙丁。丙丁不愈。加于庚辛。庚辛不死。持于壬癸。起于甲乙。肝病者。平旦慧。下晡甚。夜半静。肝欲散。急食辛以散之。用辛补之。酸泻之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jQ3jeQpNRFS', 4, '{"title":"第20200666条・脏气法时论篇第二十二","description":"<p>10、病在心。愈在长夏。长夏不愈。甚于冬。冬不死。持于春。起于夏。禁温食热衣。心病者。愈在戊己。戊己不愈。加于壬癸。壬癸不死。持于甲乙。起于丙丁。心病者。日中慧。夜半甚。平旦静。心欲耎。急食咸以耎之。用咸补之。甘泻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200666,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '10、病在心。愈在长夏。长夏不愈。甚于冬。冬不死。持于春。起于夏。禁温食热衣。心病者。愈在戊己。戊己不愈。加于壬癸。壬癸不死。持于甲乙。起于丙丁。心病者。日中慧。夜半甚。平旦静。心欲耎。急食咸以耎之。用咸补之。甘泻之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q25wwu4acx6', 4, '{"title":"第20200667条・脏气法时论篇第二十二","description":"<p>11、病在脾。愈在秋。秋不愈。甚于春。春不死。持于夏。起于长夏。禁温食饱食。湿地濡衣。脾病者。愈在庚辛。庚辛不愈。加于甲乙。甲乙不死。持于丙丁。起于戊己。脾病者。日昳慧。日出甚。下晡静。脾欲缓。急食甘以缓之。用苦泻之。甘补之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200667,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '11、病在脾。愈在秋。秋不愈。甚于春。春不死。持于夏。起于长夏。禁温食饱食。湿地濡衣。脾病者。愈在庚辛。庚辛不愈。加于甲乙。甲乙不死。持于丙丁。起于戊己。脾病者。日昳慧。日出甚。下晡静。脾欲缓。急食甘以缓之。用苦泻之。甘补之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RcOSZEYkha9', 4, '{"title":"第20200668条・脏气法时论篇第二十二","description":"<p>12、病在肺。愈在冬。冬不愈。甚于夏。夏不死。持于长夏。起于秋。禁寒饮食寒衣。肺病者。愈在壬癸。壬癸不愈。加于丙丁。丙丁不死。持于戊己。起于庚辛。肺病者。下晡慧。日中甚。夜半静。肺欲收。急食酸以收之。用酸补之。辛泻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200668,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '12、病在肺。愈在冬。冬不愈。甚于夏。夏不死。持于长夏。起于秋。禁寒饮食寒衣。肺病者。愈在壬癸。壬癸不愈。加于丙丁。丙丁不死。持于戊己。起于庚辛。肺病者。下晡慧。日中甚。夜半静。肺欲收。急食酸以收之。用酸补之。辛泻之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GeGkoeLLZLt', 4, '{"title":"第20200669条・脏气法时论篇第二十二","description":"<p>13、病在肾。愈在春。春不愈。甚于长夏。长夏不死。持于秋。起于冬。禁犯焠?。热食。温炙衣。肾病者。愈在甲乙。甲乙不愈。甚于戊己。戊己不死。持于庚辛。起于壬癸。肾病者。夜半慧。四季甚。下晡静。肾欲坚。急食苦以坚之。用苦补之。咸泻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200669,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '13、病在肾。愈在春。春不愈。甚于长夏。长夏不死。持于秋。起于冬。禁犯焠?。热食。温炙衣。肾病者。愈在甲乙。甲乙不愈。甚于戊己。戊己不死。持于庚辛。起于壬癸。肾病者。夜半慧。四季甚。下晡静。肾欲坚。急食苦以坚之。用苦补之。咸泻之。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ezI9hGGD39m', 4, '{"title":"第20200670条・脏气法时论篇第二十二","description":"<p>14、夫邪气之客于身也。以胜相加。至其所生而愈。至其所不胜而甚。至于所生而持。自得其位而起。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200670,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '14、夫邪气之客于身也。以胜相加。至其所生而愈。至其所不胜而甚。至于所生而持。自得其位而起。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CcVCTa30WbL', 4, '{"title":"第20200671条・脏气法时论篇第二十二","description":"<p>15、必先定五脏之脉。乃可言间甚之时。死生之期也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200671,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '15、必先定五脏之脉。乃可言间甚之时。死生之期也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eEDEQBgnGGU', 4, '{"title":"第20200672条・脏气法时论篇第二十二","description":"<p>16、肝病者。两胁下痛引少腹。令人善怒。虚则目**无所见。耳无所闻。善恐如人将捕之。取其经。厥阴与少阳。气逆。则头痛耳聋不。颊肿。取血者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200672,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '16、肝病者。两胁下痛引少腹。令人善怒。虚则目**无所见。耳无所闻。善恐如人将捕之。取其经。厥阴与少阳。气逆。则头痛耳聋不。颊肿。取血者。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lj6r5LN5AiV', 4, '{"title":"第20200673条・脏气法时论篇第二十二","description":"<p>17、心病者。胸中痛。胁支满。胁下痛。膺背肩甲间痛。两臂内痛，虚则胸腹大。胁下与腰相引而痛。取其经少阴太阳。舌下血者。其变病。刺郄中血者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200673,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '17、心病者。胸中痛。胁支满。胁下痛。膺背肩甲间痛。两臂内痛，虚则胸腹大。胁下与腰相引而痛。取其经少阴太阳。舌下血者。其变病。刺郄中血者。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jh1wcLbzv1K', 4, '{"title":"第20200674条・脏气法时论篇第二十二","description":"<p>18、脾病者。身重善肌肉痿。足不收行。善瘛。脚下痛。虚则腹满肠鸣。飧泄。食不化。取其经太阴阳明少阴血者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200674,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '18、脾病者。身重善肌肉痿。足不收行。善瘛。脚下痛。虚则腹满肠鸣。飧泄。食不化。取其经太阴阳明少阴血者。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SLmdDUiZ3Wc', 4, '{"title":"第20200675条・脏气法时论篇第二十二","description":"<p>19、肺病者。喘咳逆气。肩背痛。汗出尻阴股膝髀腨胻足皆痛。虚则少气不能报息。耳聋嗌干。取其经。太阴足太阳之外厥阴内血者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200675,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '19、肺病者。喘咳逆气。肩背痛。汗出尻阴股膝髀腨胻足皆痛。虚则少气不能报息。耳聋嗌干。取其经。太阴足太阳之外厥阴内血者。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PNh8yIwa9Ux', 4, '{"title":"第20200676条・脏气法时论篇第二十二","description":"<p>20、肾病者。腹大胫肿。喘咳身重。寝汗出憎风。虚则胸中痛。大腹小腹痛。清厥意不乐。取其经。少阴太阳血者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200676,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '20、肾病者。腹大胫肿。喘咳身重。寝汗出憎风。虚则胸中痛。大腹小腹痛。清厥意不乐。取其经。少阴太阳血者。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cBznSEcz7lg', 4, '{"title":"第20200677条・脏气法时论篇第二十二","description":"<p>21、肝色青。宜食甘。粳米牛肉枣葵皆甘。心色赤。宜食酸。小豆犬肉李韭皆酸。肺色白。宜食苦。麦羊肉杏薤皆苦。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200677,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '21、肝色青。宜食甘。粳米牛肉枣葵皆甘。心色赤。宜食酸。小豆犬肉李韭皆酸。肺色白。宜食苦。麦羊肉杏薤皆苦。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vevEekjyFxC', 4, '{"title":"第20200678条・脏气法时论篇第二十二","description":"<p>22、脾色黄。宜食咸。大豆豕肉栗藿皆咸。肾色黑。宜食辛。黄黍鸡肉桃葱皆辛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200678,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '22、脾色黄。宜食咸。大豆豕肉栗藿皆咸。肾色黑。宜食辛。黄黍鸡肉桃葱皆辛。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('byutU2OQhQe', 4, '{"title":"第20200679条・脏气法时论篇第二十二","description":"<p>23、辛散。酸收。甘缓。苦坚。咸緛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200679,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '23、辛散。酸收。甘缓。苦坚。咸緛。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l56DV6T7I9j', 4, '{"title":"第20200680条・脏气法时论篇第二十二","description":"<p>24、毒药攻邪。五谷为养。五果为助。五畜为益。五菜为充。气味合而服之。以补精益气。此五者。有辛酸甘苦咸。各有所利。或散或收。或缓或急。或坚或緛。四时五脏。病随五味所宜也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200680,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '24、毒药攻邪。五谷为养。五果为助。五畜为益。五菜为充。气味合而服之。以补精益气。此五者。有辛酸甘苦咸。各有所利。或散或收。或缓或急。或坚或緛。四时五脏。病随五味所宜也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'M36Pcjn228o');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dvki1Ld8L4N', 4, '{"title":"第20200681条・宣明五气篇第二十三","description":"<p>1、五味所入：酸入肝。辛入肺。苦入心。咸入肾。甘入脾。是谓五入。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200681,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、五味所入：酸入肝。辛入肺。苦入心。咸入肾。甘入脾。是谓五入。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5YTFh9qoIu5', 4, '{"title":"第20200682条・宣明五气篇第二十三","description":"<p>2、五气所病：心为噫。肺为咳。肝为语。脾为吞。肾为欠为嚏。胃为气逆为哕为恐。大肠小肠为泄。下焦溢为水。膀胱不利为癃。不约为遗溺。胆为怒。是谓五病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200682,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、五气所病：心为噫。肺为咳。肝为语。脾为吞。肾为欠为嚏。胃为气逆为哕为恐。大肠小肠为泄。下焦溢为水。膀胱不利为癃。不约为遗溺。胆为怒。是谓五病。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XeSSyr74L9R', 4, '{"title":"第20200683条・宣明五气篇第二十三","description":"<p>3、五精所并：精气并于心则喜。并于肺则悲。并于肝则忧。并于脾则畏。并于肾则恐。是谓五并。虚而相并者也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200683,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、五精所并：精气并于心则喜。并于肺则悲。并于肝则忧。并于脾则畏。并于肾则恐。是谓五并。虚而相并者也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xy0aBDK7wZK', 4, '{"title":"第20200684条・宣明五气篇第二十三","description":"<p>4、五脏所恶：心恶热。肺恶寒。肝恶风。脾恶湿。肾恶燥。是谓五恶。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200684,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、五脏所恶：心恶热。肺恶寒。肝恶风。脾恶湿。肾恶燥。是谓五恶。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yPJ5R0w9IbJ', 4, '{"title":"第20200685条・宣明五气篇第二十三","description":"<p>5、五脏化液：心为汗。肺为涕。肝为泪。脾为涎。肾为唾。是谓五液。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200685,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、五脏化液：心为汗。肺为涕。肝为泪。脾为涎。肾为唾。是谓五液。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pTLrtrKF3I1', 4, '{"title":"第20200686条・宣明五气篇第二十三","description":"<p>6、五味所禁：辛走气。气病无多食辛。咸走血。血病无多食咸。苦走骨。骨病无多食苦。甘走肉。肉病无多食甘。酸走筋。筋病无多食酸。是谓五禁。无令多食。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200686,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、五味所禁：辛走气。气病无多食辛。咸走血。血病无多食咸。苦走骨。骨病无多食苦。甘走肉。肉病无多食甘。酸走筋。筋病无多食酸。是谓五禁。无令多食。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AjVDWugNq3X', 4, '{"title":"第20200687条・宣明五气篇第二十三","description":"<p>7、五病所发：阴病发于骨。阳病发于血。阴病发于肉。阳病发于冬。阴病发于夏。是谓五发。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200687,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '7、五病所发：阴病发于骨。阳病发于血。阴病发于肉。阳病发于冬。阴病发于夏。是谓五发。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cv324q3dYU9', 4, '{"title":"第20200688条・宣明五气篇第二十三","description":"<p>8、五邪所乱：邪入于阳则狂。邪入于阴则痹。搏阳则为巅疾。搏阴则为喑。阳入之阴则静。阴出之阳则怒。是谓五乱。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200688,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '8、五邪所乱：邪入于阳则狂。邪入于阴则痹。搏阳则为巅疾。搏阴则为喑。阳入之阴则静。阴出之阳则怒。是谓五乱。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XqIm5EQLEHx', 4, '{"title":"第20200689条・宣明五气篇第二十三","description":"<p>9、五邪所见：春得秋脉。夏得冬脉。长夏得春脉。秋得夏脉。冬得长夏脉。名曰阴出之阳。病善怒不治。是谓五邪。皆同命。死不治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200689,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '9、五邪所见：春得秋脉。夏得冬脉。长夏得春脉。秋得夏脉。冬得长夏脉。名曰阴出之阳。病善怒不治。是谓五邪。皆同命。死不治。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0EfGSp3Yeg2', 4, '{"title":"第20200690条・宣明五气篇第二十三","description":"<p>10、五藏所藏：心藏神。肺藏魄。肝藏魂。脾藏意。肾藏志。是谓五脏所藏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200690,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '10、五藏所藏：心藏神。肺藏魄。肝藏魂。脾藏意。肾藏志。是谓五脏所藏。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lc5r31hrj8H', 4, '{"title":"第20200691条・宣明五气篇第二十三","description":"<p>11、五脏所主：心主脉。肺主皮。肝主筋。脾主肉。肾主骨。是谓五主。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200691,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '11、五脏所主：心主脉。肺主皮。肝主筋。脾主肉。肾主骨。是谓五主。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VU8dHYNkkRg', 4, '{"title":"第20200692条・宣明五气篇第二十三","description":"<p>12、五劳所伤：久视伤血。久卧伤气。久坐伤肉。久立伤骨。久行伤筋。是谓五劳所伤。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200692,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '12、五劳所伤：久视伤血。久卧伤气。久坐伤肉。久立伤骨。久行伤筋。是谓五劳所伤。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D6diSakw5W6', 4, '{"title":"第20200693条・宣明五气篇第二十三","description":"<p>13、五脉应象：肝脉弦。心脉钩。脾脉代。肺脉毛。肾脉石。是谓五脏之脉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200693,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '13、五脉应象：肝脉弦。心脉钩。脾脉代。肺脉毛。肾脉石。是谓五脏之脉。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'GuYRcyeLLoz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O1HIc8SI4NV', 4, '{"title":"第20200694条・血气形志篇第二十四","description":"<p>1、夫人之常数。太阳常多血少气。少阳常少血多气。阳明常多气多血。少阴常少血多气。厥阴常多血少气。太阴常多气少血。此天之常数。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200694,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、夫人之常数。太阳常多血少气。少阳常少血多气。阳明常多气多血。少阴常少血多气。厥阴常多血少气。太阴常多气少血。此天之常数。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PBvbiahpyLv', 4, '{"title":"第20200695条・血气形志篇第二十四","description":"<p>2、足太阳与少阴为表里。少阳与厥阴为表里。阳明与太阴为表里。是为足阴阳也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200695,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、足太阳与少阴为表里。少阳与厥阴为表里。阳明与太阴为表里。是为足阴阳也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mDTn5CwFo1D', 4, '{"title":"第20200696条・血气形志篇第二十四","description":"<p>3、手太阳与少阴为表里。少阳与心主为表里。阳明与太阴为表里。是为手之阴阳也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200696,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、手太阳与少阴为表里。少阳与心主为表里。阳明与太阴为表里。是为手之阴阳也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QcrhkiaGLkb', 4, '{"title":"第20200697条・血气形志篇第二十四","description":"<p>4、今知手足阴阳所苦。凡治病必先去其血。去其所苦。伺之所欲。然后泻有余。补不足。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200697,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、今知手足阴阳所苦。凡治病必先去其血。去其所苦。伺之所欲。然后泻有余。补不足。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3w35vD2EMoP', 4, '{"title":"第20200698条・血气形志篇第二十四","description":"<p>5、欲知背俞。先度其两乳间。中折之。更以他草度去半已。即以两隅相拄也。乃举以度其背。令其一隅居上。齐脊大椎。两隅在下。当其下隅者。肺之俞也。复下一度。心之俞也。复下一度。左角肝之俞也。右角脾之俞也。复下一度。肾之俞也。是谓五藏之俞。灸刺之度也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200698,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、欲知背俞。先度其两乳间。中折之。更以他草度去半已。即以两隅相拄也。乃举以度其背。令其一隅居上。齐脊大椎。两隅在下。当其下隅者。肺之俞也。复下一度。心之俞也。复下一度。左角肝之俞也。右角脾之俞也。复下一度。肾之俞也。是谓五藏之俞。灸刺之度也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z2uONzCSVCS', 4, '{"title":"第20200699条・血气形志篇第二十四","description":"<p>6、形乐志苦。病生于脉。治之以灸刺。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200699,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、形乐志苦。病生于脉。治之以灸刺。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I49v8CxdyZT', 4, '{"title":"第20200700条・血气形志篇第二十四","description":"<p>7、形乐志乐。病生于肉。治之以针石。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200700,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '7、形乐志乐。病生于肉。治之以针石。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5gk4N9pomrt', 4, '{"title":"第20200701条・血气形志篇第二十四","description":"<p>8、形苦志乐。病生于筋。治之以熨引。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '8、形苦志乐。病生于筋。治之以熨引。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ddx23AgPg5I', 4, '{"title":"第20200702条・血气形志篇第二十四","description":"<p>9、形苦志苦。病生于咽嗌。治之以百药。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200702,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '9、形苦志苦。病生于咽嗌。治之以百药。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6D4MB8jxM7t', 4, '{"title":"第20200703条・血气形志篇第二十四","description":"<p>10、形数惊恐。经络不通。病生于不仁。治之以按摩醪药。是谓五形志也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200703,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '10、形数惊恐。经络不通。病生于不仁。治之以按摩醪药。是谓五形志也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3ZLht5Yt14q', 4, '{"title":"第20200704条・血气形志篇第二十四","description":"<p>11、刺阳明出血气。刺太阳出血恶气。刺少阳出气恶血。刺太阴出气恶血。刺少阴出气恶血。刺厥阴出血恶气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200704,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '11、刺阳明出血气。刺太阳出血恶气。刺少阳出气恶血。刺太阴出气恶血。刺少阴出气恶血。刺厥阴出血恶气也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'WVgILYv6kFz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4w44lpcJOCp', 4, '{"title":"第20200705条・宝命全形论篇第二十五","description":"<p>1、黄帝问曰：天复地载。万物悉备。莫贵于人。人以天地之气生。四时之法成。君王众庶。尽欲全角。形之疾病。莫知其情。留淫日深。着于骨髓。心私虑之。余欲针除其疾病。为之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '1、黄帝问曰：天复地载。万物悉备。莫贵于人。人以天地之气生。四时之法成。君王众庶。尽欲全角。形之疾病。莫知其情。留淫日深。着于骨髓。心私虑之。余欲针除其疾病。为之奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cimo7WH4T1W', 4, '{"title":"第20200706条・宝命全形论篇第二十五","description":"<p>2、岐伯对曰：夫盐之味咸者。其气令器津泄。弦绝者。其音嘶败。木敷者。其叶发。病深者。其声哕。人有此三者。是谓坏府。毒药无治。短针无取。此皆绝皮伤肉。血气争黑。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2、岐伯对曰：夫盐之味咸者。其气令器津泄。弦绝者。其音嘶败。木敷者。其叶发。病深者。其声哕。人有此三者。是谓坏府。毒药无治。短针无取。此皆绝皮伤肉。血气争黑。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3QIFSG8LYFw', 4, '{"title":"第20200707条・宝命全形论篇第二十五","description":"<p>3、帝曰： 余念其痛。心为之乱惑反甚。其病不可更代。百姓闻之。以为残贼。为之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200707,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '3、帝曰： 余念其痛。心为之乱惑反甚。其病不可更代。百姓闻之。以为残贼。为之奈何？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hY70tInCXW1', 4, '{"title":"第20200708条・宝命全形论篇第二十五","description":"<p>4、岐伯曰：夫人生于地。悬命于天。天地合气。命之曰人。人能应四时。天地为之父母。知万物者。谓之天子。天有阴阳。人有十二节。天有寒暑。人有虚实。能经天地阴阳之化者。不失四时。知十二节之理者。圣智不能欺也。能存八动之变。五胜更立。能达虚实之数者。独出独入。呿吟至微。秋毫在目。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200708,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '4、岐伯曰：夫人生于地。悬命于天。天地合气。命之曰人。人能应四时。天地为之父母。知万物者。谓之天子。天有阴阳。人有十二节。天有寒暑。人有虚实。能经天地阴阳之化者。不失四时。知十二节之理者。圣智不能欺也。能存八动之变。五胜更立。能达虚实之数者。独出独入。呿吟至微。秋毫在目。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oGC0Dfqbqxq', 4, '{"title":"第20200709条・宝命全形论篇第二十五","description":"<p>5、帝曰：人生有形。不离阴阳。天地合气。别为九野。分为四时。月有小大。日有短长。万物并至。不可胜量。虚实呿吟。敢问其方？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200709,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '5、帝曰：人生有形。不离阴阳。天地合气。别为九野。分为四时。月有小大。日有短长。万物并至。不可胜量。虚实呿吟。敢问其方？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A4NL04L6W4j', 4, '{"title":"第20200710条・宝命全形论篇第二十五","description":"<p>6、岐伯曰：木得金而伐。火得水而灭。土得木而达。金得火而缺。水得土而绝。万物尽然。不可胜竭。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200710,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '6、岐伯曰：木得金而伐。火得水而灭。土得木而达。金得火而缺。水得土而绝。万物尽然。不可胜竭。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zP2esVVJMmq', 4, '{"title":"第20200711条・宝命全形论篇第二十五","description":"<p>7、故针有悬布天下者五。黔首共余食。莫知之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200711,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '7、故针有悬布天下者五。黔首共余食。莫知之也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H7DEC598o6s', 4, '{"title":"第20200712条・宝命全形论篇第二十五","description":"<p>8、一曰治神。二曰知养身。三曰知毒药为真。四曰制砭石小大。五曰知腑脏血气之诊。五法俱立。各有所先。今末世之刺也。虚者实之。满者泄之。此皆众工所共知也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200712,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '8、一曰治神。二曰知养身。三曰知毒药为真。四曰制砭石小大。五曰知腑脏血气之诊。五法俱立。各有所先。今末世之刺也。虚者实之。满者泄之。此皆众工所共知也。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PnxV5J1gdLg', 4, '{"title":"第20200713条・宝命全形论篇第二十五","description":"<p>9、若夫法天则地。随应而动。和之者若响。随之者若影。道无鬼神。独来独往。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200713,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '9、若夫法天则地。随应而动。和之者若响。随之者若影。道无鬼神。独来独往。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oCYaJ2E0tyC', 4, '{"title":"第20200714条・宝命全形论篇第二十五","description":"<p>10、帝曰：愿闻其道。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200714,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '10、帝曰：愿闻其道。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8yQTPa7JNKz', 4, '{"title":"第20200715条・宝命全形论篇第二十五","description":"<p>11、岐伯曰：凡刺之真。必先治神。五脏已定。九候已备。后乃存针。众脉不见。众凶弗闻。外内相得。无以形先。可玩往来。乃施于人。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200715,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '11、岐伯曰：凡刺之真。必先治神。五脏已定。九候已备。后乃存针。众脉不见。众凶弗闻。外内相得。无以形先。可玩往来。乃施于人。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7a9Ad8QE137', 4, '{"title":"第20200716条・宝命全形论篇第二十五","description":"<p>12、人有虚实。五虚勿近。五实勿远。至其当发。间不容瞚。手动若务。针耀而匀。静意视义。观适之变。是谓冥冥。莫知其形。见其乌乌。见其稷稷。从见其飞。不知其谁。伏如横弩。起如发机。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200716,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '12、人有虚实。五虚勿近。五实勿远。至其当发。间不容瞚。手动若务。针耀而匀。静意视义。观适之变。是谓冥冥。莫知其形。见其乌乌。见其稷稷。从见其飞。不知其谁。伏如横弩。起如发机。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KM07B7v5MVC', 4, '{"title":"第20200717条・宝命全形论篇第二十五","description":"<p>13、帝曰：何如而虚？何如而实？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200717,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '13、帝曰：何如而虚？何如而实？', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Exj6N3DmA6V', 4, '{"title":"第20200718条・宝命全形论篇第二十五","description":"<p>14、岐伯曰： 刺实者须其虚。刺虚者须其实。经气已至。慎守勿失。深浅在志。远近若一。如临深渊。手如握虎。神无营于众物。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200718,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '2024-09-26T13:53:12.000Z', '14、岐伯曰： 刺实者须其虚。刺虚者须其实。经气已至。慎守勿失。深浅在志。远近若一。如临深渊。手如握虎。神无营于众物。', '2024-09-26T13:53:12.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'FR0f48umbmI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A0rP2B8cbBG', 4, '{"title":"第20200719条・八正神明论篇第二十六","description":"<p>1、黄帝问曰：用针之服。必有法则焉。今何法何则？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200719,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、黄帝问曰：用针之服。必有法则焉。今何法何则？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u2PGcTmE6x2', 4, '{"title":"第20200720条・八正神明论篇第二十六","description":"<p>2、岐伯对曰：法天则地。合以天光。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200720,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、岐伯对曰：法天则地。合以天光。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nHsrUus3cSF', 4, '{"title":"第20200721条・八正神明论篇第二十六","description":"<p>3、帝曰：愿卒闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200721,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、帝曰：愿卒闻之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3birJ7Gl5fD', 4, '{"title":"第20200722条・八正神明论篇第二十六","description":"<p>4、岐伯曰：凡刺之法。必候日月星辰。四时八正之气。气定乃刺之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200722,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、岐伯曰：凡刺之法。必候日月星辰。四时八正之气。气定乃刺之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OEtmlC5n40h', 4, '{"title":"第20200723条・八正神明论篇第二十六","description":"<p>5、是故天温日明。则人血淖液而卫气浮。故血易泻。气易行。天寒日阴。则人血凝泣而卫气沉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200723,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、是故天温日明。则人血淖液而卫气浮。故血易泻。气易行。天寒日阴。则人血凝泣而卫气沉。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('84moxzL3hiq', 4, '{"title":"第20200724条・八正神明论篇第二十六","description":"<p>6、月始生。则血气始精。卫气始行。月郭满。则血气实。肌肉坚。月郭空。则肌肉减。经络虚。卫气去。形独居。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200724,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、月始生。则血气始精。卫气始行。月郭满。则血气实。肌肉坚。月郭空。则肌肉减。经络虚。卫气去。形独居。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1B7yiHc64i5', 4, '{"title":"第20200725条・八正神明论篇第二十六","description":"<p>7、是以因天时而调血气也。是以天寒无刺。天温无疑。月生无泻。月满无补。月郭空无治。是谓得时而调之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200725,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、是以因天时而调血气也。是以天寒无刺。天温无疑。月生无泻。月满无补。月郭空无治。是谓得时而调之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XQxwWK4kc8S', 4, '{"title":"第20200726条・八正神明论篇第二十六","description":"<p>8、因天之序。盛虚之时。移光定位。正立而待之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200726,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '8、因天之序。盛虚之时。移光定位。正立而待之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yQgrVoJ2PmE', 4, '{"title":"第20200727条・八正神明论篇第二十六","description":"<p>9、故曰月生而泻。是谓藏虚。月满而补。血气扬溢。络有留血。命曰重实。月郭空而治。是谓乱经。阴阳相错。真邪不别。沉以留止。外虚内乱。淫邪乃起。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200727,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '9、故曰月生而泻。是谓藏虚。月满而补。血气扬溢。络有留血。命曰重实。月郭空而治。是谓乱经。阴阳相错。真邪不别。沉以留止。外虚内乱。淫邪乃起。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O5pScBQXp4s', 4, '{"title":"第20200728条・八正神明论篇第二十六","description":"<p>10、帝曰：星辰八正何候？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200728,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '10、帝曰：星辰八正何候？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ToR2iD2DWY1', 4, '{"title":"第20200729条・八正神明论篇第二十六","description":"<p>11、岐伯曰：星辰者。所以制日月之行也。八正者。所以候八风之虚邪以时至者也。四时者。所以分春秋冬夏之气所在。以时调之。候八正之虚邪。而避之勿犯也。以身之虚。而逢天之虚。两虚相感。其气至骨。入则伤五脏。工候救之。弗能伤也。故曰：天忌不可不知也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200729,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '11、岐伯曰：星辰者。所以制日月之行也。八正者。所以候八风之虚邪以时至者也。四时者。所以分春秋冬夏之气所在。以时调之。候八正之虚邪。而避之勿犯也。以身之虚。而逢天之虚。两虚相感。其气至骨。入则伤五脏。工候救之。弗能伤也。故曰：天忌不可不知也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OEmjGYNpVEJ', 4, '{"title":"第20200730条・八正神明论篇第二十六","description":"<p>12、帝曰：善。其法星辰者。余闻之矣。愿闻法往古者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200730,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '12、帝曰：善。其法星辰者。余闻之矣。愿闻法往古者。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9wNNdkXI1vN', 4, '{"title":"第20200731条・八正神明论篇第二十六","description":"<p>13、岐伯曰： 法往古者。先知针经也。验于来今者。先知日之寒温。月之虚盛。以候气之浮沉。而调之于身。观其立有验也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200731,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '13、岐伯曰： 法往古者。先知针经也。验于来今者。先知日之寒温。月之虚盛。以候气之浮沉。而调之于身。观其立有验也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hx24XB1TPu5', 4, '{"title":"第20200732条・八正神明论篇第二十六","description":"<p>14、观于冥冥者。言形气荣卫之不形于外。而工独知之。以日之寒温。月之虚盛。四时气之浮沉。参伍相合而调之。工常先见之。然而不形于外。故曰观于冥冥焉。通于无穷者。可以传于后世也。是故工之所以异也。然而不形见于外。故俱不能见也。视之无形。尝之无味。故谓冥冥。若神仿佛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200732,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '14、观于冥冥者。言形气荣卫之不形于外。而工独知之。以日之寒温。月之虚盛。四时气之浮沉。参伍相合而调之。工常先见之。然而不形于外。故曰观于冥冥焉。通于无穷者。可以传于后世也。是故工之所以异也。然而不形见于外。故俱不能见也。视之无形。尝之无味。故谓冥冥。若神仿佛。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jXI2E87DLt3', 4, '{"title":"第20200733条・八正神明论篇第二十六","description":"<p>15、虚邪者，八正之虚邪气也。正邪者。身形若用力汗出。腠理开。逢虚风。其中人也微。故莫知其情。莫见其形。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200733,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '15、虚邪者，八正之虚邪气也。正邪者。身形若用力汗出。腠理开。逢虚风。其中人也微。故莫知其情。莫见其形。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2LBBfQBtXd1', 4, '{"title":"第20200734条・八正神明论篇第二十六","description":"<p>16、上工救其萌牙。必先见三部九候之气。尽调不败而救之。故曰上工。下工救其已成。救其已败。救其已成者。言不知三部九候之相失。因病而败之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200734,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '16、上工救其萌牙。必先见三部九候之气。尽调不败而救之。故曰上工。下工救其已成。救其已败。救其已成者。言不知三部九候之相失。因病而败之也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0nP7C7aoGAX', 4, '{"title":"第20200735条・八正神明论篇第二十六","description":"<p>17、知其所在者。知诊三部九候之病脉处而治之。故曰守其门户焉。莫知其情而见邪形也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200735,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '17、知其所在者。知诊三部九候之病脉处而治之。故曰守其门户焉。莫知其情而见邪形也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TI7VHYtBpA7', 4, '{"title":"第20200736条・八正神明论篇第二十六","description":"<p>18、帝曰： 余闻补泻。未得其意。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200736,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '18、帝曰： 余闻补泻。未得其意。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o1h48K5I2q8', 4, '{"title":"第20200737条・八正神明论篇第二十六","description":"<p>19、岐伯曰：泻必用方。方者。以气方盛也。以月方满也。以日方温也。以身方定也。以息方吸而内针。乃复候其方吸而转针。乃复候其方呼而徐引针。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200737,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '19、岐伯曰：泻必用方。方者。以气方盛也。以月方满也。以日方温也。以身方定也。以息方吸而内针。乃复候其方吸而转针。乃复候其方呼而徐引针。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bMZOgsLCIC1', 4, '{"title":"第20200738条・八正神明论篇第二十六","description":"<p>20、故曰泻必用方。其气乃行焉。补必用员。员者行也。行者移也。刺必中其荣。复以吸排针也。故员与方，非针也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200738,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '20、故曰泻必用方。其气乃行焉。补必用员。员者行也。行者移也。刺必中其荣。复以吸排针也。故员与方，非针也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LPN0PDalvkz', 4, '{"title":"第20200739条・八正神明论篇第二十六","description":"<p>21、故养神者，必知形之肥瘦。荣卫血气之盛衰。血气者。人之神。不可不谨养。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200739,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '21、故养神者，必知形之肥瘦。荣卫血气之盛衰。血气者。人之神。不可不谨养。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7GhEKt34GM5', 4, '{"title":"第20200740条・八正神明论篇第二十六","description":"<p>22、帝曰： 妙乎哉论也！合人形于阴阳四时。虚实之应。冥冥之期。其非夫子孰能通之。然夫子数言形与神。何谓形？何谓神？愿卒闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200740,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '22、帝曰： 妙乎哉论也！合人形于阴阳四时。虚实之应。冥冥之期。其非夫子孰能通之。然夫子数言形与神。何谓形？何谓神？愿卒闻之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t2gXRDy2rvH', 4, '{"title":"第20200741条・八正神明论篇第二十六","description":"<p>23、岐伯曰：请言形。形乎形。目冥冥。问其所病。索之于经。慧然在前。按之不得。不知其情。故曰形。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200741,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '23、岐伯曰：请言形。形乎形。目冥冥。问其所病。索之于经。慧然在前。按之不得。不知其情。故曰形。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qqn15LntzuF', 4, '{"title":"第20200742条・八正神明论篇第二十六","description":"<p>24、帝曰：何谓神？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200742,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '24、帝曰：何谓神？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L1hOyGyWLk0', 4, '{"title":"第20200743条・八正神明论篇第二十六","description":"<p>25、岐伯曰：请言神。神乎神。耳不闻。目明心开而志先。慧然独悟。口弗能言。俱视独见。适若昏。昭然独明。若风吹云。故曰神。三部九候为之原。九针之论不必存也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200743,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '25、岐伯曰：请言神。神乎神。耳不闻。目明心开而志先。慧然独悟。口弗能言。俱视独见。适若昏。昭然独明。若风吹云。故曰神。三部九候为之原。九针之论不必存也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6nnkTA7aqLJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Isxdkgn4mNu', 4, '{"title":"第20200744条・离合真邪论篇第二十七","description":"<p>1、黄帝问曰：余闻九针九篇。夫子乃因而九之。九九八十一篇。余尽通其意矣。经言气之盛衰。左右倾移。以上调下。以左调右。有余不足。补泻于荥输。余知之矣。此皆荣卫之倾移。虚实之所生。非邪气从外入于经也。余愿闻邪气之在经也。其病患何如？取之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200744,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、黄帝问曰：余闻九针九篇。夫子乃因而九之。九九八十一篇。余尽通其意矣。经言气之盛衰。左右倾移。以上调下。以左调右。有余不足。补泻于荥输。余知之矣。此皆荣卫之倾移。虚实之所生。非邪气从外入于经也。余愿闻邪气之在经也。其病患何如？取之奈何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HnNO1XQvKfD', 4, '{"title":"第20200745条・离合真邪论篇第二十七","description":"<p>2、岐伯对曰：夫圣人之起度数。必应于天地。故天有宿度。地有经水。人有经脉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200745,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、岐伯对曰：夫圣人之起度数。必应于天地。故天有宿度。地有经水。人有经脉。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Em5179P4UY2', 4, '{"title":"第20200746条・离合真邪论篇第二十七","description":"<p>3、天地温和。则经水安静。天寒地冻。则经水凝泣。天暑地热。则经水沸溢。卒风暴起。则经水波涌而陇起。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200746,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、天地温和。则经水安静。天寒地冻。则经水凝泣。天暑地热。则经水沸溢。卒风暴起。则经水波涌而陇起。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T0bv9rQwewX', 4, '{"title":"第20200747条・离合真邪论篇第二十七","description":"<p>4、夫邪之入于脉也。寒则血凝泣。暑则气淖泽。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200747,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、夫邪之入于脉也。寒则血凝泣。暑则气淖泽。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B8eylIw4PQz', 4, '{"title":"第20200748条・离合真邪论篇第二十七","description":"<p>5、虚邪因而入客。亦如经水之得风也。经之动脉。其至也亦时陇起。其行于脉中循循然。其至寸口中手也。时大时小。大则邪至。小则平。其行无常处。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200748,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、虚邪因而入客。亦如经水之得风也。经之动脉。其至也亦时陇起。其行于脉中循循然。其至寸口中手也。时大时小。大则邪至。小则平。其行无常处。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4xENglOTvSB', 4, '{"title":"第20200749条・离合真邪论篇第二十七","description":"<p>6、在阴与阳。不可为度。从而察之。三部九候。卒然逢之。早遏其路。吸则内针。无令气忤。静以久留。无令邪布。吸则转针。以得气为故。候呼引针。呼尽乃去。大气皆出。故命曰泻。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200749,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、在阴与阳。不可为度。从而察之。三部九候。卒然逢之。早遏其路。吸则内针。无令气忤。静以久留。无令邪布。吸则转针。以得气为故。候呼引针。呼尽乃去。大气皆出。故命曰泻。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vnrjfD577NO', 4, '{"title":"第20200750条・离合真邪论篇第二十七","description":"<p>7、帝曰：不足者补之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200750,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、帝曰：不足者补之奈何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GtD0yL9QIiL', 4, '{"title":"第20200751条・离合真邪论篇第二十七","description":"<p>8、岐伯曰：必先扪而循之。切而散之。推而按之。弹而怒之。抓而下之。通而取之。外引其门。以闭其神。呼尽内针。静以久留。以气至为故。如待所贵。不知日暮。其气以至。适而自护。候吸引针。气不得出。各在其处。推阖其门。令神气存。大气留止。故命曰补。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200751,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '8、岐伯曰：必先扪而循之。切而散之。推而按之。弹而怒之。抓而下之。通而取之。外引其门。以闭其神。呼尽内针。静以久留。以气至为故。如待所贵。不知日暮。其气以至。适而自护。候吸引针。气不得出。各在其处。推阖其门。令神气存。大气留止。故命曰补。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dniLS0XX5fJ', 4, '{"title":"第20200752条・离合真邪论篇第二十七","description":"<p>9、帝曰：候气奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200752,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '9、帝曰：候气奈何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QrdzLMCLiij', 4, '{"title":"第20200753条・离合真邪论篇第二十七","description":"<p>10、岐伯曰：夫邪去络入于经也。舍于血脉之中。寒温未相得。如涌波之起也。时来时去。故不常在。故曰方其来也。必按而止之。止而取之。无逢其冲而泻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200753,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '10、岐伯曰：夫邪去络入于经也。舍于血脉之中。寒温未相得。如涌波之起也。时来时去。故不常在。故曰方其来也。必按而止之。止而取之。无逢其冲而泻之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WcreoLWptuI', 4, '{"title":"第20200754条・离合真邪论篇第二十七","description":"<p>11、真气者，经气也。经气太虚。故曰其来不可逢。此之谓也。故曰候邪不审。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200754,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '11、真气者，经气也。经气太虚。故曰其来不可逢。此之谓也。故曰候邪不审。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dMd1adi9pEK', 4, '{"title":"第20200755条・离合真邪论篇第二十七","description":"<p>12、大气已过。泻之则真气脱。脱则不复。邪气复至。而病益蓄。故曰其往不可追。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200755,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '12、大气已过。泻之则真气脱。脱则不复。邪气复至。而病益蓄。故曰其往不可追。此之谓也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f5OBY2ra11y', 4, '{"title":"第20200756条・离合真邪论篇第二十七","description":"<p>13、不可挂以发者。待邪之至时而发针泻矣。若先若后者。血气已尽。其病不可下。故曰知其可取如发机。不知其取如扣椎。故曰知机道者不可挂以发。不知机者扣之不发。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200756,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '13、不可挂以发者。待邪之至时而发针泻矣。若先若后者。血气已尽。其病不可下。故曰知其可取如发机。不知其取如扣椎。故曰知机道者不可挂以发。不知机者扣之不发。此之谓也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('11ftmyKnPRn', 4, '{"title":"第20200757条・离合真邪论篇第二十七","description":"<p>14、帝曰：补泻奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200757,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '14、帝曰：补泻奈何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SyNmwMNzqlp', 4, '{"title":"第20200758条・离合真邪论篇第二十七","description":"<p>15、岐伯曰：此攻邪也。疾出以去盛血。而复其真气。此邪新客。溶溶未有定处也。推之则前。引之则止、逆而刺之、温血也。刺出其血。其病立已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200758,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '15、岐伯曰：此攻邪也。疾出以去盛血。而复其真气。此邪新客。溶溶未有定处也。推之则前。引之则止、逆而刺之、温血也。刺出其血。其病立已。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Md5tePfQCq', 4, '{"title":"第20200759条・离合真邪论篇第二十七","description":"<p>16、帝曰：善。然真邪以合。波陇不起。候之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200759,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '16、帝曰：善。然真邪以合。波陇不起。候之奈何？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MSZ6fMGjqnk', 4, '{"title":"第20200760条・离合真邪论篇第二十七","description":"<p>17、岐伯曰：审扪循三部九候之盛虚而调之。察其左右上下相失及相减者。审其病藏以期之。不知三部者。阴阳不别。天地不分。地以候地。天以候天。人以候人。调之中府。以定三部。故曰刺不知三部九候病脉之处。虽有大过且至。工不能禁也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200760,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '17、岐伯曰：审扪循三部九候之盛虚而调之。察其左右上下相失及相减者。审其病藏以期之。不知三部者。阴阳不别。天地不分。地以候地。天以候天。人以候人。调之中府。以定三部。故曰刺不知三部九候病脉之处。虽有大过且至。工不能禁也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ApqCa6IWxJP', 4, '{"title":"第20200761条・离合真邪论篇第二十七","description":"<p>18、诛罚无过。命曰大惑。反乱大经。真不可复。用实为虚。以邪为真。用针无义。反为气贼。夺人正气。以从为逆。 荣卫散乱。真气已失。邪独内着。绝人长命。予人天殃。不知三部九候。故不能久长。因不知合之四时五行。因加相胜。释邪攻正。绝人长命。邪之新客来也。未有定处。推之则前。引之则止、逢而泻之。其病立已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200761,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '18、诛罚无过。命曰大惑。反乱大经。真不可复。用实为虚。以邪为真。用针无义。反为气贼。夺人正气。以从为逆。 荣卫散乱。真气已失。邪独内着。绝人长命。予人天殃。不知三部九候。故不能久长。因不知合之四时五行。因加相胜。释邪攻正。绝人长命。邪之新客来也。未有定处。推之则前。引之则止、逢而泻之。其病立已。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'CwRjDMO6Wqa');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TxcculpF1vx', 4, '{"title":"第20200762条・通评虚实论篇第二十八","description":"<p>1、黄帝问曰：何谓虚实？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200762,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、黄帝问曰：何谓虚实？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0QkMM4FFVdx', 4, '{"title":"第20200763条・通评虚实论篇第二十八","description":"<p>2、岐伯对曰：邪气盛则实。精气夺则虚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200763,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、岐伯对曰：邪气盛则实。精气夺则虚。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Iu6VC4Lb4q', 4, '{"title":"第20200764条・通评虚实论篇第二十八","description":"<p>3、帝曰：虚实何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200764,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、帝曰：虚实何如？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NtEfSbOesZj', 4, '{"title":"第20200765条・通评虚实论篇第二十八","description":"<p>4、岐伯曰：气虚者肺虚也。气逆者足寒也。非其时则生。当其时则死。余脏皆如此。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200765,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、岐伯曰：气虚者肺虚也。气逆者足寒也。非其时则生。当其时则死。余脏皆如此。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4QUe03KP93O', 4, '{"title":"第20200766条・通评虚实论篇第二十八","description":"<p>5、帝曰：何谓重实？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200766,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、帝曰：何谓重实？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A9u7LK9GOL1', 4, '{"title":"第20200767条・通评虚实论篇第二十八","description":"<p>6、岐伯曰：所谓重实者。言大热病。气热脉满。是谓重实。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200767,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、岐伯曰：所谓重实者。言大热病。气热脉满。是谓重实。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OBxIOm6Rw95', 4, '{"title":"第20200768条・通评虚实论篇第二十八","description":"<p>7、帝曰：经络俱实何如？何以治之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200768,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '7、帝曰：经络俱实何如？何以治之？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JcPxRD4puoX', 4, '{"title":"第20200769条・通评虚实论篇第二十八","description":"<p>8、岐伯曰：经络皆实。是寸脉急而尺缓也。皆当治之。故曰滑则从。涩则逆也。夫虚实者。皆从其物类始。故五脏骨肉滑利。可以长久也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200769,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '8、岐伯曰：经络皆实。是寸脉急而尺缓也。皆当治之。故曰滑则从。涩则逆也。夫虚实者。皆从其物类始。故五脏骨肉滑利。可以长久也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('khRs6vPnKr2', 4, '{"title":"第20200770条・通评虚实论篇第二十八","description":"<p>9、帝曰：络气不足。经气有余。何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200770,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '9、帝曰：络气不足。经气有余。何如？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8q2Wh4yEhcL', 4, '{"title":"第20200771条・通评虚实论篇第二十八","description":"<p>10、岐伯曰：络气不足。经气有余者。脉口热而尺寒也。秋冬为逆。春夏为从。治主病者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200771,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '10、岐伯曰：络气不足。经气有余者。脉口热而尺寒也。秋冬为逆。春夏为从。治主病者。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
