INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MtcjGemR15P', 4, '{"title":"第20200807条・通评虚实论篇第二十八","description":"<p>46、帝曰：春亟治经络。夏亟治经俞。秋亟治六腑。冬则闭塞。闭塞者。用药而少针石也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200807,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '46、帝曰：春亟治经络。夏亟治经俞。秋亟治六腑。冬则闭塞。闭塞者。用药而少针石也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p536ykER25C', 4, '{"title":"第20200808条・通评虚实论篇第二十八","description":"<p>47、所谓少针石者。非痈疽之谓也。痈疽不得顷时回。痈不知所。按之不应手。乍来乍已。刺手太阴旁三痏与缨脉各二。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200808,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '47、所谓少针石者。非痈疽之谓也。痈疽不得顷时回。痈不知所。按之不应手。乍来乍已。刺手太阴旁三痏与缨脉各二。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BY2NL4xCvsC', 4, '{"title":"第20200809条・通评虚实论篇第二十八","description":"<p>48、掖痈大热。刺足少阳五。刺而热不止。刺手心主三。刺手太阴经络者大骨之会各三。暴痈筋。随分而痛。魄汗不尽。胞气不足。治在经俞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200809,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '48、掖痈大热。刺足少阳五。刺而热不止。刺手心主三。刺手太阴经络者大骨之会各三。暴痈筋。随分而痛。魄汗不尽。胞气不足。治在经俞。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bCVlYGRECyE', 4, '{"title":"第20200810条・通评虚实论篇第二十八","description":"<p>49、腹暴满。按之不下。取手太阳经络者。胃之募也。少阴俞去脊椎三寸旁五。用员利针。霍乱。刺俞旁五。足阳明及上旁三。刺痫惊脉五。针手太阴各五，刺经太阳五。刺手少阴经络旁者一。足阳明一。上踝五寸刺三针。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200810,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '49、腹暴满。按之不下。取手太阳经络者。胃之募也。少阴俞去脊椎三寸旁五。用员利针。霍乱。刺俞旁五。足阳明及上旁三。刺痫惊脉五。针手太阴各五，刺经太阳五。刺手少阴经络旁者一。足阳明一。上踝五寸刺三针。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aYQ8nTw0oDH', 4, '{"title":"第20200811条・通评虚实论篇第二十八","description":"<p>50、凡治消瘅仆击。偏枯痿厥。气满发逆。甘肥贵人。则高梁之疾也。隔塞闭绝。上下不通。则暴忧之病也。暴厥而聋。偏塞闭不通。内气暴薄也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200811,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '50、凡治消瘅仆击。偏枯痿厥。气满发逆。甘肥贵人。则高梁之疾也。隔塞闭绝。上下不通。则暴忧之病也。暴厥而聋。偏塞闭不通。内气暴薄也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p7rdcz0HeaU', 4, '{"title":"第20200812条・通评虚实论篇第二十八","description":"<p>51、不从内外中风之病。故瘦留着也。跖跛。寒风湿之病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200812,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '51、不从内外中风之病。故瘦留着也。跖跛。寒风湿之病也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S9j40TLfNvD', 4, '{"title":"第20200813条・通评虚实论篇第二十八","description":"<p>52、黄帝曰：黄胆暴痛。癫疾厥狂。久逆之所生也。五藏不平。六腑闭塞之所生也。头痛耳鸣。九窍不利。肠胃之所生也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200813,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '52、黄帝曰：黄胆暴痛。癫疾厥狂。久逆之所生也。五藏不平。六腑闭塞之所生也。头痛耳鸣。九窍不利。肠胃之所生也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', '6psq6IJOEQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cym6jRfiOJb', 4, '{"title":"第20200814条・太阴阳明论篇第二十九","description":"<p>1、黄帝问曰：太阴阳明为表里。脾胃脉也。生病而异者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200814,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '1、黄帝问曰：太阴阳明为表里。脾胃脉也。生病而异者何也？', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bA8Z0Xnr9ru', 4, '{"title":"第20200815条・太阴阳明论篇第二十九","description":"<p>2、岐伯对曰：阴阳异位。更虚更实。更逆更从。或从内。或从外。所从不同。故病异名也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200815,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2、岐伯对曰：阴阳异位。更虚更实。更逆更从。或从内。或从外。所从不同。故病异名也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l8teyVP7Obb', 4, '{"title":"第20200816条・太阴阳明论篇第二十九","description":"<p>3、帝曰：愿闻其异状也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200816,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '3、帝曰：愿闻其异状也。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Af7an0QsmUQ', 4, '{"title":"第20200817条・太阴阳明论篇第二十九","description":"<p>4、岐伯曰：阳者。天气也。主外。阴者。地气也。主内。故阳道实。阴道虚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200817,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '4、岐伯曰：阳者。天气也。主外。阴者。地气也。主内。故阳道实。阴道虚。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UT6lckpCnZm', 4, '{"title":"第20200818条・太阴阳明论篇第二十九","description":"<p>5、故犯贼风虚邪者。阳受之。食饮不节起居不时者。阴受之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200818,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '5、故犯贼风虚邪者。阳受之。食饮不节起居不时者。阴受之。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DXS7tWorX5c', 4, '{"title":"第20200819条・太阴阳明论篇第二十九","description":"<p>6、阳受之则入六腑。阴受之则入五藏。入六腑则身热不时卧。上为喘呼。入五藏则䐜满闭塞。下为飧泄。久为肠澼。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20200819,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '2024-09-26T13:53:13.000Z', '6、阳受之则入六腑。阴受之则入五藏。入六腑则身热不时卧。上为喘呼。入五藏则䐜满闭塞。下为飧泄。久为肠澼。', '2024-09-26T13:53:13.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'q8YUoIucSZ3');
